import{c as a,Q as r,j as i,m as s}from"./chunks/framework.zngmBtT6.js";const h=JSON.parse('{"title":"Guide — Créer une release GitHub manuelle","description":"","frontmatter":{},"headers":[],"relativePath":"ressources/github-release.md","filePath":"ressources/github-release.md"}'),t={name:"ressources/github-release.md"};function l(n,e,o,u,p,c){return r(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="guide-—-creer-une-release-github-manuelle" tabindex="-1">Guide — Créer une release GitHub manuelle <a class="header-anchor" href="#guide-—-creer-une-release-github-manuelle" aria-label="Permalink to &quot;Guide — Créer une release GitHub manuelle&quot;">​</a></h1><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Publier l&#39;installateur d&#39;une application WPF sur GitHub sous forme de <em>release manuelle</em>.<br> Cette procédure permet à toute personne de <strong>télécharger et d’exécuter</strong> l&#39;installateur d’une application.</p><h2 id="etapes-a-suivre" tabindex="-1">Étapes à suivre <a class="header-anchor" href="#etapes-a-suivre" aria-label="Permalink to &quot;Étapes à suivre&quot;">​</a></h2><h3 id="_1-creer-l-installateur-de-l-application-wpf" tabindex="-1">1. Créer l&#39;installateur de l&#39;application WPF <a class="header-anchor" href="#_1-creer-l-installateur-de-l-application-wpf" aria-label="Permalink to &quot;1. Créer l&#39;installateur de l&#39;application WPF&quot;">​</a></h3><p>Suivre la <a href="./../ressources/setup">procédure détaillée</a> qui sera également présentée en classe à la semaine 12.</p><hr><h3 id="_2-preparer-le-fichier-a-publier" tabindex="-1">2. Préparer le fichier à publier <a class="header-anchor" href="#_2-preparer-le-fichier-a-publier" aria-label="Permalink to &quot;2. Préparer le fichier à publier&quot;">​</a></h3><p>À partir de l&#39;explorateur windows et du dossier <code>Release</code> se trouvant dans le dossier du projet installateur, créez une archive contenant les 2 fichiers <code>.exe</code> et <code>.msi</code>. L&#39;archive doit avoir un nom qui ressemblerait à <code>NomDeVotreApplication-v1.0.0.zip</code>.</p><hr><h3 id="_3-creer-une-release-sur-github" tabindex="-1">3. Créer une release sur GitHub <a class="header-anchor" href="#_3-creer-une-release-sur-github" aria-label="Permalink to &quot;3. Créer une release sur GitHub&quot;">​</a></h3><ol><li>Ouvrir la page du dépôt GitHub.</li><li>Cliquer sur l’onglet <strong>Releases</strong>. (dans le sidebar à droite)</li><li>Sélectionner <strong>Create a new release</strong>.</li><li>Remplir les champs :</li></ol><ul><li><strong>Tag version</strong> → <code>v1.0.0</code> (Select tag / créer un nouveau tag / Create new tag)</li><li><strong>Target</strong> → <code>main</code></li><li><strong>Title</strong> → <code>Version 1.0.0</code></li><li><strong>Description</strong> → inscrire les nouveautés ou correctifs :<div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Nouveautés :</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Ajout du module de recherche</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Amélioration de la performance</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Corrections :</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Résolution du bogue d’affichage</span></span></code></pre></div></li></ul><ol start="5"><li>Glisser le fichier d&#39;installation <code>MonApplication-v1.0.0.zip</code> dans la section <strong>Attach binaries</strong>.</li><li>Cliquer sur <strong>Publish release</strong>.</li></ol><p>La page de release sera disponible à une adresse du type : <a href="https://github.com/nom-utilisateur/nom-repo/releases/tag/v1.0.0" target="_blank" rel="noreferrer">https://github.com/nom-utilisateur/nom-repo/releases/tag/v1.0.0</a></p>`,15)])])}const g=a(t,[["render",l]]);export{h as __pageData,g as default};
